import{_ as t,o as i,c as n,a4 as a}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse('{"title":"ADR-0020 — Attribution de licence : déclarée au manifeste, non désactivable, servie par le Core","description":"Extrait de docs/adr/0020-attribution-de-licence-declaree-au-manifeste.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0020 — Attribution de licence : déclarée au manifeste, non désactivable, servie par le Core","description":"Extrait de docs/adr/0020-attribution-de-licence-declaree-au-manifeste.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0020-attribution-de-licence-declaree-au-manifeste.md","filePath":"developpeurs/adr/0020-attribution-de-licence-declaree-au-manifeste.md"}'),r={name:"developpeurs/adr/0020-attribution-de-licence-declaree-au-manifeste.md"};function s(o,e,l,c,d,u){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0020--attribution-de-licence--déclarée-au-manifeste-non-désactivable-servie-par-le-core" tabindex="-1">ADR-0020 — Attribution de licence : déclarée au manifeste, non désactivable, servie par le Core <a class="header-anchor" href="#adr-0020--attribution-de-licence--déclarée-au-manifeste-non-désactivable-servie-par-le-core" aria-label="Permalink to &quot;ADR-0020 — Attribution de licence : déclarée au manifeste, non désactivable, servie par le Core {#adr-0020--attribution-de-licence--déclarée-au-manifeste-non-désactivable-servie-par-le-core}&quot;">​</a></h1><p><strong>Date :</strong> 21 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §11.2 (fond OpenStreetMap, licence ODbL) ; Epic E14</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le fond de plan OpenStreetMap est publié sous licence <strong>ODbL</strong>. L&#39;afficher oblige à créditer les contributeurs — dans les crédits de la carte <strong>et</strong> dans les mentions légales du site. Le CDC le pose comme une exigence, et ajoute qu&#39;elle doit être <strong>vérifiée à chaque déploiement de site</strong> (usine à sites, CDC §9.3).</p><p>Trois faits rendent cette obligation particulièrement facile à perdre :</p><ol><li><strong>Le défaut est invisible.</strong> Une carte sans crédit fonctionne parfaitement. Rien ne remonte, aucun écran ne s&#39;allume, aucun test fonctionnel ne casse.</li><li><strong>Le CMS ne génère aucune page de mentions légales.</strong> L&#39;Epic E15 produit une politique de protection des données et une déclaration d&#39;accessibilité — pas des mentions légales. Il n&#39;existait donc aucun document dans lequel écrire la mention.</li><li><strong>L&#39;obligation naît et disparaît avec un plugin.</strong> Un site qui n&#39;affiche aucune carte ne doit rien à OpenStreetMap ; lui faire revendiquer une source qu&#39;il n&#39;affiche pas rendrait le reste de ses mentions légales moins croyable.</li></ol><p>La question à trancher : <strong>où vit une obligation de crédit</strong>, et sous quelle forme, alors que le document qui l&#39;affichera n&#39;existe pas encore.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p>Une <strong>donnée du manifeste de plugin</strong>, <code>AttributionRequirement</code>, agrégée par organisation dans un registre du Core (<code>app/compliance/attributions.py</code>) et servie par <code>GET /api/v1/compliance/attributions</code>.</p><p>Quatre propriétés, chacune répondant à une façon dont l&#39;obligation aurait pu se perdre :</p><ol><li><p><strong>Déclarée par le plugin qui crée l&#39;obligation, jamais écrite dans un gabarit.</strong> Le plugin sait ce qu&#39;il affiche ; le Core ne le sait pas. Une mention rédigée dans un gabarit de bloc disparaît au premier thème qui redéfinit ce gabarit — et personne ne voit qu&#39;elle a disparu.</p></li><li><p><strong>Non désactivable, et dans le type.</strong> <code>required: Literal[True]</code> et <code>dismissible: Literal[False]</code> sont des <code>Literal</code> à une seule valeur : il n&#39;y a rien à décider, donc rien à décocher. C&#39;est la discipline déjà retenue pour <code>GeneratedDocumentDisclaimer</code> (E15 : <code>position=&quot;heading&quot;</code>, <code>dismissible=False</code>) et pour <code>FormConfig.review_step</code> / <code>captcha</code> (E11). Un booléen aurait été une infraction à un clic.</p></li><li><p><strong>Calculée depuis les plugins <em>actifs sur cette organisation</em>, jamais depuis un catalogue figé.</strong> Installer la cartographie fait naître le crédit ; la désinstaller le lève. Le registre est reconstruit par requête comme les sept autres registres d&#39;extension (E7), avec la même raison : un état partagé entre organisations produirait la panne la plus difficile à diagnostiquer d&#39;un CMS multi-organisation.</p></li><li><p><strong>Servie par l&#39;API de conformité, pas par celle des plugins.</strong> Ce n&#39;est pas une propriété du plugin, c&#39;est une <strong>obligation du site</strong> — même rayon que la politique de données et la déclaration d&#39;accessibilité. Conséquence pratique : la vérification que le CDC demande à chaque déploiement devient une requête HTTP dont la réponse est vide ou ne l&#39;est pas, au lieu d&#39;une relecture de gabarit par un humain pressé.</p></li></ol><p>Le texte voyage en clair <strong>et</strong> en clé i18n (<code>text</code> + <code>text_key</code>), pour la raison exacte d&#39;E15 : un front sans catalogue de traduction doit afficher la mention plutôt que son identifiant technique. Une attribution rendue « <code>plugins.cartography.attribution.openstreetmap</code> » ne crédite personne et ne satisfait pas la licence.</p><p><strong>Ce que cette ADR ne décide pas :</strong> la page de mentions légales elle-même. Elle n&#39;existe pas, elle relève d&#39;un Epic à venir, et la construire ici l&#39;aurait été sans son cadrage. Ce qui est livré est son <strong>point d&#39;ancrage</strong> : le jour où ce document sera écrit, il lira ce registre plutôt que d&#39;inventer sa propre liste — exactement comme la politique de protection des données lit le registre des traitements d&#39;E5 au lieu de redécrire les traitements.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Écrire la mention dans le gabarit du bloc cartographique</strong></td><td>Un thème qui redéfinit le gabarit fait disparaître l&#39;obligation légale, silencieusement. Et le CDC demande la mention <em>aussi</em> dans les mentions légales, c&#39;est-à-dire hors du bloc.</td></tr><tr><td><strong>Documenter la règle et compter sur l&#39;intégrateur</strong></td><td>C&#39;est précisément ce que le CDC refuse en demandant une vérification <strong>à chaque déploiement</strong> : une consigne qui dépend de la vigilance ne survit pas à l&#39;usine à sites.</td></tr><tr><td><strong>Réutiliser <code>ThirdPartyService</code> (registre cookies, E5)</strong></td><td>Deux obligations différentes envers deux personnes différentes : le consentement protège le <strong>visiteur</strong> (les tuiles exposent son adresse IP), l&#39;attribution crédite l&#39;<strong>auteur des données</strong>. Les confondre aurait fait disparaître le crédit dès qu&#39;un visiteur refuse les cookies — c&#39;est-à-dire au pire moment. Le service <code>openstreetmap</code> reste d&#39;ailleurs dans le catalogue du Core depuis E5, et le plugin ne le redéclare pas : <code>register_third_party_service()</code> refuserait le doublon, et deux vérités sur le même service valent moins qu&#39;une.</td></tr><tr><td><strong>Un booléen <code>attribution_required</code> sur le <code>BlockManifest</code></strong></td><td>Dit qu&#39;une attribution est due sans dire laquelle, ni sous quelle licence, ni avec quel texte. Un écran de mentions légales n&#39;a alors rien à afficher, et le booléen ne sert qu&#39;à se donner bonne conscience.</td></tr><tr><td><strong>Stocker les attributions en base, par site</strong></td><td>Une obligation de licence n&#39;est pas un réglage de site : elle découle de ce que le code affiche. La ranger en base aurait permis de la modifier — c&#39;est-à-dire de l&#39;effacer — depuis un écran d&#39;administration.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>L&#39;obligation ODbL est portée par une donnée que personne ne peut désactiver, et qui apparaît à l&#39;installation du plugin sans geste supplémentaire.</li><li>La vérification de déploiement demandée par le CDC est mécanisable : un appel HTTP, une liste attendue.</li><li>Le mécanisme est générique. Le prochain contenu sous licence (fond IGN, jeu de données ouvertes, police de caractères, bibliothèque cartographique tierce) déclare son crédit de la même façon, sans nouveau code du Core.</li><li>L&#39;écran d&#39;administration des plugins montre l&#39;attribution parmi ce qu&#39;un plugin <strong>apporte</strong> (<code>provides.attributions</code>) : un administrateur voit, avant de cliquer, quelle obligation il crée — et laquelle il lèverait en désinstallant.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Rien ne vérifie que le front affiche réellement la mention.</strong> L&#39;API la déclare et la sert ; un thème qui l&#39;ignore reste en infraction. C&#39;est la limite structurelle de tout ce qui touche au rendu dans ce dépôt (<code>apps/api</code> n&#39;a aucune couche de gabarit), et elle vaut déjà pour <code>aria-live</code> (E3) et pour l&#39;avertissement en tête des documents générés (E15). Le contrôle correspondant appartient à la recette du front.</li><li>La route sert les attributions <strong>de l&#39;organisation</strong>, pas du site. Une organisation multi-sites dont un seul site affiche une carte verra la mention rappelée pour tous. C&#39;est le bon défaut — mieux vaut créditer une source de trop que l&#39;oublier — mais il devra être affiné quand l&#39;usine à sites (E10) rendra les compositions réellement distinctes par site.</li><li>Le texte français est figé dans le manifeste du plugin. Le changer demande un déploiement, là où une clé i18n seule aurait suffi ; c&#39;est le prix assumé de la garantie « un front sans catalogue affiche quand même la mention ».</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] <code>AttributionRequirement</code>, <code>AttributionRegistry</code>, <code>register_attribution()</code> (<code>apps/api/app/compliance/attributions.py</code>) — huitième point d&#39;extension du SDK, <strong>aucune migration</strong>.</li><li>[x] <code>PluginManifest.attributions</code>, agrégation par organisation (<code>plugin_attributions</code>, <code>ExtensionRegistries</code>) et exposition dans <code>provides</code> — Epic E14.</li><li>[x] <code>GET /api/v1/compliance/attributions</code> (<code>apps/api/app/api/compliance.py</code>).</li><li>[x] Premier usage : <code>ATTRIBUTION_OSM</code> (ODbL 1.0, « © les contributeurs OpenStreetMap ») dans le plugin cartographie.</li><li>[x] Recette : <code>test_l_attribution_openstreetmap_est_due_et_non_desactivable</code> (<code>apps/api/tests/test_cartography.py</code>) — absence sans plugin, apparition à l&#39;installation, non-désactivabilité, disparition à la désinstallation.</li><li>[ ] Epic « mentions légales » : assembler le document depuis ce registre, jamais depuis une liste écrite à la main.</li><li>[ ] Epic multi-site (E10) : décider si les attributions se calculent par site plutôt que par organisation, quand les compositions seront distinctes par site.</li><li>[ ] Recette du front : vérifier que la mention est rendue dans les crédits de la carte <strong>et</strong> dans les mentions légales — l&#39;API ne peut pas le garantir. → <em>18/09/2026 :</em> la notice (§7.10) confie explicitement cette vérification à l&#39;exploitant, pour chaque site et chaque site créé depuis un modèle. Case laissée ouverte : c&#39;est une recette par site, qui ne se clôt pas une fois pour toutes.</li></ul>',22)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
